/**
 * The single environment contract for Teaching Journey (TEACH-26, ADR 0015 / 0010).
 *
 * Every variable any app, package, script or CI job reads is declared here **once**, with where
 * it lives (local `.env` files, Railway, Vercel, CI) and who sets it. Everything else is derived:
 *
 *   - `docs/env.md`, every `.env.example` and `.gitleaks.toml` are GENERATED by
 *     `bun run env:generate` (`--check` in CI fails when they drift);
 *   - `bun run doctor` validates the local `.env` files against it;
 *   - `bun run env:check` compares the variable NAMES on Railway / Vercel against it;
 *   - `apps/<app>/src/env.contract.test.ts` assert that each app's Zod schema and this file agree;
 *   - `scripts/env-contract.test.ts` asserts `turbo.json#env` lists only declared names.
 *
 * This file has no dependencies (it is imported by root scripts and by every app's tests) and
 * contains NO VALUES that are secret: `local` holds the synthetic docker-compose defaults only.
 * Names are the unit of truth; values live in the provider (Railway / Vercel) or in a gitignored
 * `.env`. Edit this file, then run `bun run env:generate`.
 */

/** Who reads the variable. `compose` = docker compose + the root scripts (root `.env`). */
export type EnvService = "api" | "worker" | "web" | "ci" | "compose";

/** `secret` values are never printed, never in git and get a gitleaks rule; `config` is public. */
export type EnvScope = "secret" | "config";

/** Which Railway environments carry the variable (`n/a` = not a Railway variable). */
export type RailwayTarget = "prod" | "pr" | "both" | "n/a";

/** Which Vercel environments carry the variable (`n/a` = not a Vercel variable). */
export type VercelTarget = "prod" | "preview" | "both" | "n/a";

/**
 * How the provider value comes into being:
 * - `reference` — a Railway reference/template (`${{postgres.POSTGRES_PASSWORD}}`), set by
 *   `infra/railway/provision.sh`;
 * - `template` — a plain config value seeded by `provision.sh` / `vercel env add`;
 * - `generated` — random, created by `bun run setup` (local) or `provision.sh` (Railway);
 * - `manual` — a human pastes it (OAuth credentials, tokens, domains).
 */
export type EnvSetBy = "reference" | "manual" | "template" | "generated";

/** The `.env.example` files `bun run env:generate` writes. */
export type EnvFile = "root" | "api" | "worker" | "web" | "db" | "jobs";

/** What `bun run doctor` validates when a value is present locally. */
export type EnvFormat =
  | "url"
  | "postgres-url"
  | "port"
  | "int"
  | "enum"
  | "origin-list"
  | "origin-pattern-list"
  | "string";

/** Where a variable appears in a `.env.example`, optionally commented-out or with another value. */
export type EnvPlacement =
  | EnvFile
  | {
      file: EnvFile;
      /** Emit as `# NAME=` (documented, opt-in). Defaults to `local === null`. */
      commented?: boolean;
      /** Per-file value when it differs from `local` (e.g. the worker's `PORT`). */
      value?: string;
    };

export interface EnvVar {
  readonly name: string;
  readonly services: readonly EnvService[];
  readonly scope: EnvScope;
  /**
   * Value written to `.env.example` for the local compose stack, or `null` when the variable is
   * optional / not needed locally (then it is emitted commented-out where `files` lists it).
   */
  readonly local: string | null;
  readonly railway: RailwayTarget;
  readonly vercel: VercelTarget;
  readonly setBy?: EnvSetBy;
  /** One or two sentences; becomes the comment above the key in `.env.example` and the docs. */
  readonly description: string;
  /** `.env.example` files that carry the key. Empty = provider/CI-only or shell-only. */
  readonly files?: readonly EnvPlacement[];
  /** Validation `doctor` applies to a present local value (default: none). */
  readonly format?: EnvFormat;
  /** Allowed values when `format === "enum"`. */
  readonly values?: readonly string[];
  /**
   * Read outside the service's boot-time Zod schema (tests, `vite.config.ts`, build scripts,
   * platform-injected) — the schema-parity tests do not expect it in `EnvSchema`.
   */
  readonly runtimeOnly?: boolean;
  /**
   * Non-secret value (or Railway reference) that `infra/railway/provision.sh` seeds on the api /
   * worker services via `scripts/railway-vars.ts`. Secrets never have one.
   */
  readonly railwayValue?: string;
}

