export type EnvName = (typeof CONTRACT)[number]["name"];

/** Every declared variable, in matrix order (element type widened to `EnvVar` with a narrow name). */
export const ENV_CONTRACT: readonly (EnvVar & { readonly name: EnvName })[] = CONTRACT;

/** `ENV.DATABASE_URL === "DATABASE_URL"` — use these instead of string literals. */
export const ENV = Object.fromEntries(ENV_CONTRACT.map((v) => [v.name, v.name])) as {
  readonly [K in EnvName]: K;
};

/** `turbo.json#env` may also list these globs (Turborepo wildcard syntax). */
export const TURBO_ENV_GLOBS = ["PLAYWRIGHT_*"] as const;

