// --- derived views (pure helpers shared by the generators, doctor and env:check) -----------------

export interface ResolvedPlacement {
  readonly file: EnvFile;
  readonly commented: boolean;
  /** `null` only when commented (no example value). */
  readonly value: string | null;
}

/** Normalises `files` for one variable. */
export function placementsOf(v: EnvVar): ResolvedPlacement[] {
  return (v.files ?? []).map((p) => {
    const placement = typeof p === "string" ? { file: p } : p;
    const value = placement.value ?? v.local;
    return {
      file: placement.file,
      commented: placement.commented ?? value === null,
      value,
    };
  });
}

/** Variables (in contract order) that appear in `file`, with their resolved placement. */
export function varsForFile(file: EnvFile): { v: EnvVar; placement: ResolvedPlacement }[] {
  const out: { v: EnvVar; placement: ResolvedPlacement }[] = [];
  for (const v of ENV_CONTRACT) {
    const placement = placementsOf(v).find((p) => p.file === file);
    if (placement) out.push({ v, placement });
  }
  return out;
}

/**
 * Keys `doctor` requires in the `.env` next to `file`: every uncommented key of the example plus
 * `generated` secrets (which the example only documents commented-out, but `setup` creates).
 */
export function requiredKeysForFile(file: EnvFile): string[] {
  return varsForFile(file)
    .filter(({ v, placement }) => !placement.commented || v.setBy === "generated")
    .map(({ v }) => v.name);
}

/** Contract names a given service reads (schema + runtime-only). */
export function namesForService(service: EnvService): string[] {
  return ENV_CONTRACT.filter((v) => (v.services as readonly EnvService[]).includes(service)).map(
    (v) => v.name,
  );
}

/** Names the service's boot-time Zod schema is expected to declare (excludes `runtimeOnly`). */
export function schemaNamesForService(service: EnvService): string[] {
  return ENV_CONTRACT.filter(
    (v) => (v.services as readonly EnvService[]).includes(service) && !v.runtimeOnly,
  ).map((v) => v.name);
}

export type RailwayEnvironment = "production" | "pr";
export type VercelEnvironment = "production" | "preview";

/** Names expected on the Railway service `api` / `worker` in `environment`. */
export function railwayNames(service: "api" | "worker", environment: RailwayEnvironment): string[] {
  const want: RailwayTarget = environment === "production" ? "prod" : "pr";
  return ENV_CONTRACT.filter(
    (v) =>
      (v.services as readonly EnvService[]).includes(service) &&
      (v.railway === "both" || v.railway === want),
  ).map((v) => v.name);
}

/** Names expected on the Vercel project in `environment`. */
export function vercelNames(environment: VercelEnvironment): string[] {
  const want: VercelTarget = environment === "production" ? "prod" : "preview";
  return ENV_CONTRACT.filter(
    (v) =>
      (v.services as readonly EnvService[]).includes("web") &&
      (v.vercel === "both" || v.vercel === want),
  ).map((v) => v.name);
}

/** Secret-scoped names (gitleaks rules, rotation docs). */
export function secretNames(): string[] {
  return ENV_CONTRACT.filter((v) => v.scope === "secret").map((v) => v.name);
}

/** Look a variable up by name. */
export function envVar(name: string): EnvVar | undefined {
  return ENV_CONTRACT.find((v) => v.name === name);
}
